/**
 * LLM Eval Tracker — tool-local actions.
 *
 * Category: AI Quality / Eval Tools (squad S12a, Wave 4)
 * Tool:     Log eval scores per (model, dataset, prompt-version) over time,
 *           detect regressions / trends, compare models on a dataset.
 *
 * Agent surface: tool.llm_eval_tracker.*
 * Backing CRUD : workspace.llm_eval.* (auto-generated by defineCrudActions
 *                in src/lib/actions/workspace/index.ts)
 *
 * ─── CRUD-BACKED + PURE-COMPUTE hybrid pattern ───────────────────────
 * LLM evals are append-only records (one row per (model, dataset, prompt)
 * measurement). The generic CRUD surface — workspace.llm_eval.* — handles
 * raw create / list / update / delete. This file adds VERBS THE AGENT
 * WANTS TO SPEAK in the eval-tracking domain vocabulary, plus a pure
 * compute the agent can call during planning ("did this model regress?")
 * without round-tripping through the workspace:
 *
 *   1. list_state    — read: snapshot + grouped summaries (byModel,
 *                      byDataset, byPromptVersion). Lets the agent answer
 *                      "what's the state of my evals?" in one round-trip
 *                      instead of paging through every individual row and
 *                      re-bucketing client-side.
 *   2. record_eval   — write: append a new eval entry. Convenience over
 *                      workspace.llm_eval.create — pre-fills id, defaults
 *                      recordedAt to now, surfaces just the (model, dataset,
 *                      score, [promptVersion], [metricBreakdown], [notes])
 *                      knobs the agent typically thinks about.
 *                      requiresConfirmation:false — logging a metric is
 *                      non-destructive and the natural agent phrasing
 *                      ("log this eval result") would be unbearable to
 *                      confirm individually.
 *   3. compute_trend — read, PURE: given an array of evals + a window,
 *                      returns {byModel: trend, changePct, sampleSize}.
 *                      No workspace mutation; no mcpHandler. The agent
 *                      typically already has eval data in scope (just
 *                      called list_state) and wants a quick "is this
 *                      regressing?" classification without persisting.
 *   4. compare_models — read: filter to one dataset, group by model,
 *                       return per-model {avgScore, sampleSize, latestScore}
 *                       sorted by avgScore desc. Surfaces the "which
 *                       model is winning on dataset X right now?" question
 *                       the agent would otherwise need 4 calls to answer.
 *
 * ─── ENTITY KIND ──────────────────────────────────────────────────────────
 * Server-side entity kind: "workspace:llmEval"  (camelCase)
 * Browser sync registers : "workspace:llmEval"  (camelCase)
 *
 * Both sides use the same camelCase kind: the workspace store's
 * registerCollection() maps the camelCase JavaScript-side collection name
 * onto the sync kind, and the server-side kindFromToolId() camelCases the
 * suffix of `workspace.llm_eval` (the defineCrudActions toolId) — both
 * yielding `workspace:llmEval`.
 *
 * Consequence: an eval RECORDED via the MCP path is written under
 * `workspace:llmEval` and round-trips into the browser workspace store on
 * next pull-from-server, and vice versa. The MCP-path read/write is
 * internally consistent (record_eval → list_state via MCP both see the
 * same rows), the browser-path read/write is internally consistent
 * (record_eval → list_state via the in-app agent both see
 * `useWorkspaceStore.getState().llmEvals`), and cross-path round-trips.
 *
 * Use server kind "workspace:llmEval" for all serverGetEntity /
 * serverUpsertEntity / serverListEntities calls in this file — matches
 * what the auto-generated CRUD surface writes.
 *
 * ─── ID NAMING ───────────────────────────────────────────────────────
 * Namespace is `tool.llm_eval_tracker` (snake_case). The user-facing
 * tool route is /llm-eval-tracker (kebab-case), but kebab is illegal
 * in tool ids — snake_case is the canonical action-namespace form.
 * ─────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverUpsertEntity } from "../server-store";
import type { LLMEval } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.llm_eval")
 *  used by the auto-generated CRUD in src/lib/actions/workspace/index.ts,
 *  so reads/writes here line up byte-for-byte with the generic surface and
 *  with the browser sync engine's "workspace:llmEval" collection. */
const KIND_LLM_EVAL = "workspace:llmEval";

const ws = () => useWorkspaceStore.getState();

function nowIso(): string {
  return new Date().toISOString();
}

/** Newest-first by recordedAt. An unparseable recordedAt (record_eval takes
 *  any string) sorts as the oldest: subtracting raw NaN times made the
 *  comparator non-transitive, so valid rows stayed out of order and
 *  "first sighting = latest" picked the wrong score. */
function byRecordedAtDesc(a: LLMEval, b: LLMEval): number {
  const ms = (e: LLMEval) => {
    const t = new Date(e.recordedAt).getTime();
    return Number.isFinite(t) ? t : -Infinity;
  };
  const ta = ms(a);
  const tb = ms(b);
  return ta === tb ? 0 : tb - ta;
}

// ──────── tool.llm_eval_tracker.list_state ────────
// Snapshot + grouped summary stats. The agent's opening question for
// the eval tracker is "what's the state of my evals?" — returning items
// (sorted recordedAt desc) AND breakdowns byModel, byDataset, and
// byPromptVersion in one round-trip means the agent never has to
// re-bucket the same data three times.
registry.register({
  id: "tool.llm_eval_tracker.list_state",
  toolId: "tool.llm_eval_tracker",
  name: "list_state",
  category: "read",
  description:
    "List all LLM evals in the workspace with grouped summary stats. Returns {total, byModel: Record<model, {count, latestScore, avgScore}>, byDataset: Record<dataset, {count, avgScore}>, byPromptVersion: Record<version, {count, avgScore}>, items: LLMEval[] sorted by recordedAt desc}.",
  paramsSchema: z.object({}),
  handler: async () => {
    const items = ws().llmEvals ?? [];
    return summarize(items);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<LLMEval>(ctx.userId, KIND_LLM_EVAL);
    return summarize(items);
  },
});

/** Build the {total, byModel, byDataset, byPromptVersion, items} response.
 *  Kept as a single helper so the browser-path and MCP-path responses
 *  are guaranteed byte-identical — drift would mean an agent gets a
 *  different shape depending on whether it's invoked from chat or MCP. */
function summarize(items: LLMEval[]): ListStateResult {
  // Pre-sort once; we reuse for the items field AND latestScore lookup
  // (latest per model = first encountered when iterating desc).
  const sorted = [...items].sort(byRecordedAtDesc);

  // Accumulator: collect sum + count + latestScore per bucket, then
  // derive avgScore at the end. Building the latestScore in one pass
  // avoids a second sort-per-bucket.
  const modelAcc = new Map<string, { sum: number; count: number; latestScore: number }>();
  const datasetAcc = new Map<string, { sum: number; count: number }>();
  const promptAcc = new Map<string, { sum: number; count: number }>();

  // Iterate `sorted` (recordedAt desc) so the FIRST time we see a model
  // is also its most recent entry — that's the latestScore.
  for (const e of sorted) {
    const m = modelAcc.get(e.model);
    if (m) {
      m.sum += e.score;
      m.count += 1;
      // Do NOT overwrite latestScore — first sighting (desc order) wins.
    } else {
      modelAcc.set(e.model, { sum: e.score, count: 1, latestScore: e.score });
    }

    const d = datasetAcc.get(e.dataset);
    if (d) {
      d.sum += e.score;
      d.count += 1;
    } else {
      datasetAcc.set(e.dataset, { sum: e.score, count: 1 });
    }

    // promptVersion is optional — bucket by literal string so an absent
    // version doesn't get conflated with a row that explicitly carries
    // "default". The agent can read byPromptVersion["(unversioned)"] if
    // it wants the unversioned cohort.
    const pv = e.promptVersion ?? "(unversioned)";
    const p = promptAcc.get(pv);
    if (p) {
      p.sum += e.score;
      p.count += 1;
    } else {
      promptAcc.set(pv, { sum: e.score, count: 1 });
    }
  }

  const byModel: Record<string, { count: number; latestScore: number; avgScore: number }> = {};
  modelAcc.forEach((v, k) => {
    byModel[k] = {
      count: v.count,
      latestScore: v.latestScore,
      avgScore: v.sum / v.count,
    };
  });

  const byDataset: Record<string, { count: number; avgScore: number }> = {};
  datasetAcc.forEach((v, k) => {
    byDataset[k] = { count: v.count, avgScore: v.sum / v.count };
  });

  const byPromptVersion: Record<string, { count: number; avgScore: number }> = {};
  promptAcc.forEach((v, k) => {
    byPromptVersion[k] = { count: v.count, avgScore: v.sum / v.count };
  });

  return {
    total: items.length,
    byModel,
    byDataset,
    byPromptVersion,
    items: sorted,
  };
}

interface ListStateResult {
  total: number;
  byModel: Record<string, { count: number; latestScore: number; avgScore: number }>;
  byDataset: Record<string, { count: number; avgScore: number }>;
  byPromptVersion: Record<string, { count: number; avgScore: number }>;
  items: LLMEval[];
}

// ──────── tool.llm_eval_tracker.record_eval ────────
// Append a new eval entry. Convenience over workspace.llm_eval.create —
// pre-generates the id, defaults recordedAt to now, and surfaces only
// the fields the agent typically thinks about when logging a score.
//
// requiresConfirmation:false — logging a metric is non-destructive,
// and the natural agent loop ("run eval → log score → run next eval")
// would be unbearable to confirm individually.
registry.register({
  id: "tool.llm_eval_tracker.record_eval",
  toolId: "tool.llm_eval_tracker",
  name: "record_eval",
  category: "write",
  requiresConfirmation: false,
  description:
    "Append a new LLM eval entry to the workspace. Returns {id} of the created row. recordedAt defaults to now if omitted.",
  paramsSchema: z.object({
    model: z.string().min(1).max(200).describe("Model identifier (e.g. gpt-5, claude-opus-4-7)"),
    dataset: z
      .string()
      .min(1)
      .max(200)
      .describe("Dataset / benchmark name (e.g. faithfulness-v2, mmlu)"),
    score: z
      .number()
      .min(0)
      .max(1)
      .describe("Eval score in [0, 1] — accuracy, faithfulness, or similar normalized metric"),
    promptVersion: z
      .string()
      .max(200)
      .optional()
      .describe("Optional prompt version this eval was run against (e.g. greet@1.4.0)"),
    metricBreakdown: z
      .record(z.string(), z.number())
      .optional()
      .describe("Optional per-metric breakdown (e.g. {precision: 0.9, recall: 0.85})"),
    notes: z
      .string()
      .max(2000)
      .optional()
      .describe("Optional freeform notes (eval conditions, seed, etc.)"),
    recordedAt: z.string().optional().describe("ISO-8601 timestamp; defaults to now if omitted"),
  }),
  handler: async (params) => {
    const item: LLMEval = {
      id: `llmEval_${Math.random().toString(36).slice(2, 10)}`,
      model: params.model,
      dataset: params.dataset,
      score: params.score,
      promptVersion: params.promptVersion,
      metricBreakdown: params.metricBreakdown,
      notes: params.notes,
      recordedAt: params.recordedAt ?? nowIso(),
    };
    ws().upsertLLMEval(item);
    return { id: item.id };
  },
  mcpHandler: async (params, ctx) => {
    const item: LLMEval = {
      id: `llmEval_${Math.random().toString(36).slice(2, 10)}`,
      model: params.model,
      dataset: params.dataset,
      score: params.score,
      promptVersion: params.promptVersion,
      metricBreakdown: params.metricBreakdown,
      notes: params.notes,
      recordedAt: params.recordedAt ?? nowIso(),
    };
    await serverUpsertEntity<LLMEval>(ctx.userId, KIND_LLM_EVAL, item);
    return { id: item.id };
  },
});

// ──────── tool.llm_eval_tracker.compute_trend ────────
// PURE: given evals + a window, classify each model's trend as
// up / down / flat with a magnitude. The agent feeds eval data it
// already has (typically the items[] from a list_state call), so no
// workspace round-trip is needed — and the calculation is referentially
// transparent (same inputs, same output) so no mcpHandler.
//
// FORMULA:
//   1. Filter to evals within the last `windowDays` (default 30) by
//      recordedAt. Items outside the window are ignored entirely.
//   2. For each model, sort the in-window evals by recordedAt ascending.
//   3. Split the window in half by COUNT (not time) — first half =
//      baseline, second half = recent. Splitting by count keeps the
//      sample sizes balanced even when measurements are clustered at
//      one end of the window.
//   4. baselineMean = mean(first half), recentMean = mean(second half).
//   5. changePct = (recentMean - baselineMean) / baselineMean * 100.
//      When baselineMean = 0, changePct = 0 (avoid div-by-zero;
//      flat-line at zero is unambiguously "flat" by definition).
//   6. trend classification:
//        - |changePct| < 2.0  → "flat"  (within noise floor)
//        - changePct >= 2.0   → "up"    (improving)
//        - changePct <= -2.0  → "down"  (regressing)
//      The 2% threshold mirrors the noise floor an eval typically has
//      across runs — within ~2pp is "didn't move".
//   7. Models with < 2 in-window samples can't have a split → omitted
//      from the result entirely (the agent can spot missing models in
//      its input list if it cares).
registry.register({
  id: "tool.llm_eval_tracker.compute_trend",
  toolId: "tool.llm_eval_tracker",
  name: "compute_trend",
  category: "read",
  description:
    "Pure compute: classify per-model trend over a recent window from a provided eval array. Returns {byModel: Record<model, {trend: 'up' | 'down' | 'flat', changePct: number, sampleSize: number}>}. Split-by-count over the windowed half (baseline = older half, recent = newer half). Models with <2 in-window samples are omitted. windowDays defaults to 30.",
  paramsSchema: z.object({
    evals: z
      .array(
        z.object({
          id: z.string().optional(),
          model: z.string(),
          dataset: z.string().optional(),
          score: z.number(),
          recordedAt: z.string(),
          promptVersion: z.string().optional(),
          metricBreakdown: z.record(z.string(), z.number()).optional(),
          notes: z.string().optional(),
        })
      )
      .min(0)
      .max(10_000),
    windowDays: z
      .number()
      .int()
      .min(1)
      .max(365)
      .default(30)
      .describe("Lookback window in days. Evals older than now-windowDays are ignored."),
  }),
  handler: async (params) => {
    const windowDays = params.windowDays ?? 30;
    const cutoffMs = Date.now() - windowDays * 24 * 60 * 60 * 1000;

    // Filter to in-window evals. Defensive against malformed recordedAt:
    // NaN dates compare to false on every comparison so they fall out.
    const inWindow = params.evals.filter((e) => {
      const t = new Date(e.recordedAt).getTime();
      return Number.isFinite(t) && t >= cutoffMs;
    });

    // Group by model.
    const byModelEvals = new Map<string, typeof inWindow>();
    for (const e of inWindow) {
      const arr = byModelEvals.get(e.model);
      if (arr) arr.push(e);
      else byModelEvals.set(e.model, [e]);
    }

    const byModel: Record<
      string,
      { trend: "up" | "down" | "flat"; changePct: number; sampleSize: number }
    > = {};

    byModelEvals.forEach((evals, model) => {
      // Can't compute a trend from a single point — need at least 2 so
      // the split has one row per side.
      if (evals.length < 2) return;

      // Sort ascending by time so first half = baseline (older),
      // second half = recent.
      const sortedAsc = [...evals].sort(
        (a, b) => new Date(a.recordedAt).getTime() - new Date(b.recordedAt).getTime()
      );
      const mid = Math.floor(sortedAsc.length / 2);
      // Odd-length arrays: drop the middle item (treat it as "neither
      // recent nor baseline") so baseline/recent stay balanced. This
      // matches what people intuitively expect from a "first half vs
      // second half" split.
      const baseline = sortedAsc.slice(0, mid);
      const recent = sortedAsc.length % 2 === 1 ? sortedAsc.slice(mid + 1) : sortedAsc.slice(mid);

      // Edge case: when there are exactly 2 evals, mid = 1, baseline =
      // [0], recent = [1] (length 1 each). When there are 3, mid = 1,
      // baseline = [0], recent = [2] (we drop index 1). Both produce
      // valid means.
      if (baseline.length === 0 || recent.length === 0) return;

      const baselineMean = baseline.reduce((s, x) => s + x.score, 0) / baseline.length;
      const recentMean = recent.reduce((s, x) => s + x.score, 0) / recent.length;

      // Div-by-zero guard: when baselineMean = 0, we can't compute a
      // meaningful relative change — call it flat. (An eval that flat-lined
      // at zero and then jumped to non-zero is a real signal, but the
      // changePct semantics are undefined; the agent can spot it in the
      // raw items if it cares.)
      const changePct = baselineMean === 0 ? 0 : ((recentMean - baselineMean) / baselineMean) * 100;

      // Noise floor: 2% absolute change is the rough threshold below
      // which an eval shift is indistinguishable from measurement noise.
      let trend: "up" | "down" | "flat";
      if (Math.abs(changePct) < 2) trend = "flat";
      else if (changePct > 0) trend = "up";
      else trend = "down";

      byModel[model] = {
        trend,
        changePct,
        sampleSize: evals.length,
      };
    });

    return { byModel };
  },
  // No mcpHandler — pure compute runs identically on server and client.
});

// ──────── tool.llm_eval_tracker.compare_models ────────
// {dataset, since?} → per-model leaderboard for that dataset, sorted
// by avgScore desc. The agent asking "which model wins on faithfulness-v2
// right now?" otherwise needs list_state → filter to dataset → group by
// model → sort — four operations the LLM is bad at composing reliably.
//
// `since` is an ISO-8601 cutoff (inclusive). Omit for all-time. Useful
// when an agent wants "leader on dataset X over the last quarter".
registry.register({
  id: "tool.llm_eval_tracker.compare_models",
  toolId: "tool.llm_eval_tracker",
  name: "compare_models",
  category: "read",
  description:
    "Leaderboard of models on a single dataset. Returns {models: [{model, avgScore, sampleSize, latestScore}]} sorted by avgScore desc. Optional ISO-8601 `since` filter (inclusive); omitted = all-time.",
  paramsSchema: z.object({
    dataset: z
      .string()
      .min(1)
      .max(200)
      .describe("Dataset name to compare across models (e.g. faithfulness-v2)"),
    since: z
      .string()
      .optional()
      .describe("ISO-8601 cutoff (inclusive). Evals recorded before this are ignored."),
  }),
  handler: async (params) => {
    const items = ws().llmEvals ?? [];
    return compareModels(items, params.dataset, params.since);
  },
  mcpHandler: async (params, ctx) => {
    const items = await serverListEntities<LLMEval>(ctx.userId, KIND_LLM_EVAL);
    return compareModels(items, params.dataset, params.since);
  },
});

/** Shared compare-models implementation. Filters to one dataset (and
 *  optionally a `since` cutoff), buckets by model, and returns a sorted
 *  leaderboard. Single helper to guarantee browser-path / MCP-path
 *  return shapes stay byte-identical. */
function compareModels(
  items: LLMEval[],
  dataset: string,
  since: string | undefined
): { models: Array<{ model: string; avgScore: number; sampleSize: number; latestScore: number }> } {
  // Date cutoff: when `since` is unparseable, treat as no cutoff
  // (NaN.getTime() comparisons always fail; we'd silently drop
  // everything — surfacing that as "no data" would mislead the agent).
  const sinceMs = since ? new Date(since).getTime() : NaN;
  const hasCutoff = Number.isFinite(sinceMs);

  const filtered = items.filter((e) => {
    if (e.dataset !== dataset) return false;
    if (!hasCutoff) return true;
    const t = new Date(e.recordedAt).getTime();
    return Number.isFinite(t) && t >= sinceMs;
  });

  // Sort once descending so the first encounter of each model = its
  // latestScore (same trick as summarize() above).
  const sortedDesc = [...filtered].sort(byRecordedAtDesc);

  const acc = new Map<string, { sum: number; count: number; latestScore: number }>();
  for (const e of sortedDesc) {
    const cur = acc.get(e.model);
    if (cur) {
      cur.sum += e.score;
      cur.count += 1;
      // Don't overwrite latestScore — desc order means first hit wins.
    } else {
      acc.set(e.model, { sum: e.score, count: 1, latestScore: e.score });
    }
  }

  const models: Array<{
    model: string;
    avgScore: number;
    sampleSize: number;
    latestScore: number;
  }> = [];
  acc.forEach((v, model) => {
    models.push({
      model,
      avgScore: v.sum / v.count,
      sampleSize: v.count,
      latestScore: v.latestScore,
    });
  });

  // Descending leaderboard. Stable tiebreaker on model name keeps
  // consecutive calls returning the same order — agents that diff
  // compare_models responses won't see noise from same-score swaps.
  models.sort((a, b) => {
    if (b.avgScore !== a.avgScore) return b.avgScore - a.avgScore;
    return a.model.localeCompare(b.model);
  });

  return { models };
}
